import { writeFile, readFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { openApiDocument } from "../../../apps/server/src/openapi.ts";

const destination = fileURLToPath(
  new URL("../src/content/docs/docs/reference/http.md", import.meta.url),
);

const lines = [
  "---",
  "title: HTTP API reference",
  "description: Routes and schemas generated from the executable Sandbar OpenAPI contract.",
  "---",
  "",
  "> Generated by `bun run --cwd apps/docs reference:generate` from `apps/server/src/openapi.ts`. Edit that executable contract, not this page.",
  "",
  `OpenAPI **${openApiDocument.openapi}** · contract version **${openApiDocument.info.version}**. [Download the complete JSON contract](https://github.com/pandemicsyn/sandbar/blob/af06bb6/apps/server/openapi.json). Responses and schemas below describe the current development API.`,
  "",
  "Protected service operations accept a Bearer token or a session cookie unless an operation overrides security. `GET /v1/session` is cookie-only. Setup and session creation declare no HTTP security scheme but require credentials in their request bodies (`setupToken` and `token`, respectively). Cookie-authenticated mutations require `X-CSRF-Token` from `GET /v1/session`. `Origin` is optional and, when supplied, must match the configured public origin; an absent `Origin` is accepted. Project IDs appear in project-scoped paths. Sandbox create, destroy, execution and file-write requests declare an `Idempotency-Key` header; consult the full OpenAPI JSON for schema constraints and status-specific responses.",
  "",
  "## Endpoints",
  "",
  "| Method | Path | Operation | Parameters | Success | Request schema |",
  "|---|---|---|---|---|---|",
];

for (const [path, pathItem] of Object.entries(openApiDocument.paths)) {
  for (const [method, operation] of Object.entries(pathItem)) {
    if (!["get", "post", "put", "patch", "delete", "head", "options", "trace"].includes(method))
      continue;

    const successes = Object.entries(operation.responses ?? {})
      .filter(([status]) => /^2\d\d$/.test(status))
      .map(([status]) => status)
      .join(", ");

    const body = operation.requestBody?.content;
    const schema = body && Object.values(body)[0]?.schema;
    const name = schema?.$ref?.split("/").at(-1) ?? (schema ? "inline" : "—");

    const parameters =
      [...(pathItem.parameters ?? []), ...(operation.parameters ?? [])]
        .map(
          (parameter) =>
            `\`${parameter.name}\` (${parameter.in}${parameter.required ? ", required" : ""})`,
        )
        .join("<br>") || "—";

    lines.push(
      `| ${method.toUpperCase()} | \`${path}\` | \`${operation.operationId ?? "—"}\` | ${parameters} | ${successes || "—"} | ${name} |`,
    );
  }
}

lines.push(
  "",
  "## Schema names",
  "",
  "The following names are derived from the same OpenAPI document. Use the [full JSON contract](https://github.com/pandemicsyn/sandbar/blob/af06bb6/apps/server/openapi.json) for required fields, types and response envelopes.",
  "",
);

lines.push(
  Object.keys(openApiDocument.components.schemas)
    .sort()
    .map((name) => `- \`${name}\``)
    .join("\n"),
  "",
);

const output = lines.join("\n");

if (process.argv.includes("--check")) {
  if ((await readFile(destination, "utf8").catch(() => "")) !== output) {
    console.error("HTTP reference drift: run bun run --cwd apps/docs reference:generate");
    process.exitCode = 1;
  }
} else await writeFile(destination, output);
